enum LoginError: Error { case wrongPassword, noNetwork, server(code: Int) }

func login(_ user: String, _ pass: String) async throws(LoginError) -> Session {
    do {
        return try await api.login(user, pass)
    } catch let e as URLError where e.code == .notConnectedToInternet {
        throw .noNetwork
    } catch {
        throw .server(code: (error as NSError).code)
    }
}

do {
    let session = try await login("a", "b")
} catch .wrongPassword { showWrongPassword()
} catch .noNetwork     { showOffline()
} catch                { showGeneric() }
